SELECT COLUMN_NAME FROM ALL_TAB_COLUMNS WHERE OWNER='SMS' AND TABLE_NAME='CS_ACCOUNT_ACTION' AND (COLUMN_NAME LIKE '%CROSS%' OR COLUMN_NAME LIKE '%REF%' OR COLUMN_NAME LIKE '%DEPOSIT%' OR COLUMN_NAME LIKE '%STATUS%' OR COLUMN_NAME IN ('ID','ACCOUNT_ID','ACTION_TYPE_ID','ACTION_CLASS','ACTION_DATE','AMOUNT','POOL_ID')) ORDER BY COLUMN_NAME;
